import{_ as a,a0 as p,w as i,s as u,I as t,x as s,a1 as r,A as n,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"如何在 Linux 上使用 SSHfs 挂载一个远程文件系统 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上使用 SSHfs 挂载一个远程文件系统 | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上使用 SSHfs 挂载一个远程文件系统 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上使用 SSHfs 挂载一个远程文件系统 | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20151027 How to Use SSHfs to Mount a Remote Filesystem on Linux","title":"如何在 Linux 上使用 SSHfs 挂载一个远程文件系统","tag":"201511","desc":""},"relativePath":"201511/20151027 How to Use SSHfs to Mount a Remote Filesystem on Linux.md","filePath":"[post].md"}'),f={name:"201511/20151027 How to Use SSHfs to Mount a Remote Filesystem on Linux.md"};function d(m,e,S,h,x,w){const o=p("Link");return i(),u("div",null,[e[17]||(e[17]=t("h1",{id:"如何在-linux-上使用-sshfs-挂载一个远程文件系统",tabindex:"-1"},[s("如何在 Linux 上使用 SSHfs 挂载一个远程文件系统 "),t("a",{class:"header-anchor",href:"#如何在-linux-上使用-sshfs-挂载一个远程文件系统","aria-label":"Permalink to “如何在 Linux 上使用 SSHfs 挂载一个远程文件系统”"},"​")],-1)),e[18]||(e[18]=t("p",null,"你曾经想过用安全 shell 挂载一个远程文件系统到本地吗？如果有的话，SSHfs 也许就是你所需要的。它通过使用 SSH 和 Fuse（LCTT 译注：Filesystem in Userspace，用户态文件系统，是 Linux 中用于挂载某些网络空间，如 SSH，到本地文件系统的模块） 允许你挂载远程计算机（或者服务器）到本地。",-1)),t("p",null,[e[1]||(e[1]=t("strong",null,"注意",-1)),e[2]||(e[2]=s("： 这篇文章假设你明白",-1)),r(o,{href:"https://www.maketecheasier.com/setup-ssh-ubuntu/"},{default:n(()=>[...e[0]||(e[0]=[s("SSH 如何工作并在你的系统中配置 SSH",-1)])]),_:1}),e[3]||(e[3]=s("。",-1))]),e[19]||(e[19]=l(`<h3 id="准备" tabindex="-1">准备 <a class="header-anchor" href="#准备" aria-label="Permalink to “准备”">​</a></h3><p>在使用 SSHfs 挂载之前，需要进行一些设置 - 在你的系统上安装 SSHfs 以及 fuse 软件包。你还需要为 fuse 创建一个组，添加用户到组，并创建远程文件系统将会驻留的目录。</p><p>要在 Ubuntu Linux 上安装两个软件包，只需要在终端窗口输入以下命令：</p><pre><code>sudo apt-get install sshfs fuse
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/sshfs-install-fuse-ubuntu.jpg" alt="ubuntu 安装 sshfs-fuse"></p><p>如果你使用的不是 Ubuntu，那就在你的发行版软件包管理器中搜索软件包名称。最好搜索和 fuse 或 SSHfs 相关的关键字，因为取决于你运行的系统，软件包名称可能稍微有些不同。</p><p>在你的系统上安装完软件包之后，就该创建好 fuse 组了。在你安装 fuse 的时候，应该会在你的系统上创建一个组。如果没有的话，在终端窗口中输入以下命令以便在你的 Linux 系统中创建组：</p><pre><code>sudo groupadd fuse
</code></pre><p>添加了组之后，把你的用户添加到这个组。</p><pre><code>sudo gpasswd -a &quot;$USER&quot; fuse
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/sshfs-add-user-to-fuse-group.png" alt="sshfs 添加用户到组 fuse"></p><p>别担心上面命令的 <code>$USER</code>。shell 会自动用你自己的用户名替换。处理了和组相关的工作之后，就是时候创建要挂载远程文件的目录了。</p><pre><code>mkdir ~/remote_folder
</code></pre><p>在你的系统上创建了本地目录之后，就可以通过 SSHfs 挂载远程文件系统了。</p><h3 id="挂载远程文件系统" tabindex="-1">挂载远程文件系统 <a class="header-anchor" href="#挂载远程文件系统" aria-label="Permalink to “挂载远程文件系统”">​</a></h3><p>要在你的机器上挂载远程文件系统，你需要在终端窗口中输入一段较长的命令。</p><pre><code>sshfs -o idmap=user username@ip.address:/remote/file/system/ ~/remote
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/sshfs-mount-file-system-to-local-folder.png" alt="sshfs 挂载文件系统到本地目录1"></p><p><strong>注意</strong>： 也可以通过 SSH 密钥文件挂载 SSHfs 文件系统。只需要在上面的命中用 <code>sshfs -o IdentityFile=~/.ssh/keyfile</code>, 替换 <code>sshfs -o idmap=user</code> 部分。</p><p>输入这个命令之后，会提示你输入远程用户的密码。如果登录成功了，你的远程文件系统就会被挂载到之前创建的 <code>~/remote_folder</code> 目录。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/sshfs-mount-file-system-to-local-folder-2.jpg" alt="sshfs挂载文件系统到本地目录2"></p><p>使用完了你的远程文件系统，想要卸载它？容易吗？只需要在终端输入下面的命令：</p><pre><code>sudo umount ~/remote_folder
</code></pre><p>这个简单的命令会断开远程连接同时清空 remote_folder 目录。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>在 Linux 上有很多工具可以用于访问远程文件并挂载到本地。但是如之前所说，如果有的话，也只有很少的工具能充分利用 SSH 的强大功能。我希望在这篇指南的帮助下，也能认识到 SSHfs 是一个多么强大的工具。</p><p>你觉得 SSHfs 怎么样呢？在下面的评论框里告诉我们吧！</p><hr>`,28)),t("p",null,[e[5]||(e[5]=s("via: ",-1)),r(o,{href:"https://www.maketecheasier.com/sshfs-mount-remote-filesystem-linux/"},{default:n(()=>[...e[4]||(e[4]=[s("https://www.maketecheasier.com/sshfs-mount-remote-filesystem-linux/",-1)])]),_:1})]),t("p",null,[e[9]||(e[9]=s("作者：",-1)),r(o,{href:"https://www.maketecheasier.com/author/derrikdiener/"},{default:n(()=>[...e[6]||(e[6]=[s("Derrik Diener",-1)])]),_:1}),e[10]||(e[10]=s(" 译者：",-1)),r(o,{href:"http://mutouxiaogui.cn/blog/"},{default:n(()=>[...e[7]||(e[7]=[s("ictlyh",-1)])]),_:1}),e[11]||(e[11]=s(" 校对：",-1)),r(o,{href:"https://github.com/wxy"},{default:n(()=>[...e[8]||(e[8]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[14]||(e[14]=s("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[12]||(e[12]=[s("LCTT",-1)])]),_:1}),e[15]||(e[15]=s(" 原创编译，",-1)),r(o,{href:"https://linux.cn/"},{default:n(()=>[...e[13]||(e[13]=[s("Linux中国",-1)])]),_:1}),e[16]||(e[16]=s(" 荣誉推出",-1))])])}const g=a(f,[["render",d]]);export{T as __pageData,g as default};
